package com.veyra.partner;import com.veyra.security.CurrentUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/partner/{partnerId}/team")public class PartnerTeamController{private final JdbcTemplate db;public PartnerTeamController(JdbcTemplate d){db=d;}public record Add(UUID userId,String role){}
 @GetMapping List<Map<String,Object>>list(@PathVariable UUID partnerId){owner(partnerId);return db.queryForList("select pu.id,pu.user_id,pu.partner_role,pu.status,u.email,u.first_name,u.last_name from partner_users pu join users u on u.id=pu.user_id where pu.partner_id=?",partnerId);}
 @PostMapping void add(@PathVariable UUID partnerId,@RequestBody Add a){owner(partnerId);if(!Set.of("PARTNER_OWNER","PARTNER_STAFF","PARTNER_FINANCE").contains(a.role()))throw new IllegalArgumentException();db.update("insert into partner_users(partner_id,user_id,partner_role) values (?,?,?) on conflict(partner_id,user_id) do update set partner_role=excluded.partner_role,status='ACTIVE'",partnerId,a.userId(),a.role());}
 private void owner(UUID p){Integer n=db.queryForObject("select count(*) from partner_users where partner_id=? and user_id=? and partner_role='PARTNER_OWNER' and status='ACTIVE'",Integer.class,p,CurrentUser.id());if(n==0)throw new org.springframework.security.access.AccessDeniedException("owner");}
}